<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Companies</title><link rel="stylesheet" href="/assets/css/legacy-style.css"><link rel="stylesheet" href="/assets/css/app.css"></head><body><main class="card card-wide"><h1>Companies</h1><div class="button-group"><a class="btn btn-secondary" href="/companies/export/csv">Export CSV</a><a class="btn btn-secondary" href="/companies/export/pdf" target="_blank" rel="noopener">Export PDF</a></div><table class="table"><thead><tr><th>ID</th><th>Name</th><th>Subdomain</th><th>Phone</th><th>Email</th><th>Tax</th><th>VAT</th><th>Status</th><th>Created</th></tr></thead><tbody><?php if (($rows ?? []) === []): ?><tr><td colspan="9">No companies found.</td></tr><?php else: foreach ($rows as $r): ?><tr><td><?= (int) $r['company_id'] ?></td><td><?= htmlspecialchars($r['company_name'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($r['subdomain'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars((string) ($r['phone'] ?? ''), ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars((string) ($r['email'] ?? ''), ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars((string) ($r['tax_number'] ?? ''), ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars((string) ($r['vat_number'] ?? ''), ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($r['status'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($r['created_at'], ENT_QUOTES, 'UTF-8') ?></td></tr><?php endforeach; endif; ?></tbody></table><p><a href="/dashboard">Back to Dashboard</a></p></main></body></html>
